// src/cardEffects/deepHyren.ts
registerCardEffect("Deep Hyren", {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- static region check mirroring the
  // sweep half of resolvePower below (the sacrifice-target choice itself is irrelevant to Clover).
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId, options, powerName) => {
    if (powerName !== "Hurricane") return false;
    const specifiedRegion = regionForTargetFilter(state, "Orothe");
    return getOpponents(state, actingPlayerId).some(
      (opp) => opp.activeMagi && !effectiveRegions(state, cardDb, opp.activeMagi).includes(specifiedRegion)
    );
  },
  powerTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Hurricane") return;
    if (ctx.chosenTargetId === void 0) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== "Creature") return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, target.instanceId, void 0, void 0, ctx.rng);
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (!effectiveRegions(ctx.state, ctx.cardDb, creature).includes(regionForTargetFilter(ctx.state, "Orothe"))) {
        discardEnergy(ctx.state, ctx.cardDb, creature, 3, void 0, void 0, ctx.rng);
      }
    }
    for (const magi of allMagiInPlay(ctx.state)) {
      if (!effectiveRegions(ctx.state, ctx.cardDb, magi).includes(regionForTargetFilter(ctx.state, "Orothe"))) {
        discardEnergy(ctx.state, ctx.cardDb, magi, 3, void 0, void 0, ctx.rng);
      }
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. (powerTargets above is the sacrifice-target picker, an
  // unrestricted "your own Creatures" pool -- only the board-sweep clause is in scope.)
  specifiedTargetRegions: () => ["Orothe"]
});

