// src/cardEffects/izmer.ts
var SANDOMANCY_PENDING = "izmerSandomancyPending";
registerCardEffect("Izmer", {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, opposingCreatures(state, cardDb, playerId), opposingMagi(state, cardDb, playerId)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Abrade") return;
    if (ctx.chosenTargetId === void 0) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, "Creature")) return;
    if (target.controllerId === ctx.controllingPlayer.playerId) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 1, void 0, void 0, ctx.rng);
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId === self.instanceId) return;
    if (played.controllerId !== self.controllerId) return;
    const playedDef = cardDb.get(played.definitionKey);
    if (playedDef?.card_type !== "Relic") return;
    if (!playedDef.regions.includes("d'Resh")) return;
    if (allCreaturesInPlay(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, SANDOMANCY_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(SANDOMANCY_PENDING)) return void 0;
    const pool3 = allCreaturesInPlay(state, cardDb);
    if (pool3.length === 0) return void 0;
    return { prompt: "Izmer's Sandomancy: choose a Creature to discard 1 energy from", pool: pool3 };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, SANDOMANCY_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c2) => c2.instanceId === chosenInstanceId);
    if (target) discardEnergy(state, cardDb, target, 1, "effect", void 0, rng);
  }
});

// src/cardEffects/flameTrulb.ts
registerCardEffect("Flame Trulb", {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    const own = creaturesControlledBy(state, cardDb, self.controllerId);
    const selfAlreadyCounted = own.some((c2) => c2.instanceId === self.instanceId);
    const selfRegions = cardDb.get(self.definitionKey)?.regions ?? [];
    const selfBonus = (region) => !selfAlreadyCounted && selfRegions.includes(region) ? 1 : 0;
    const bograth = effectiveBograthCreatureCount(state, cardDb, self.controllerId) + selfBonus("Bograth");
    const cald = own.filter((c2) => effectiveRegions(state, cardDb, c2).includes("Cald")).length + selfBonus("Cald");
    const amount = Math.min(bograth, cald);
    if (amount > 0) addEnergy(state, cardDb, self, amount, "effect");
  },
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allCreaturesInPlay(state, cardDb), allMagiInPlay(state)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Fireball") return;
    if (ctx.chosenTargetId === void 0) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, "Creature")) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 1, void 0, void 0, ctx.rng);
  }
});

