// src/cardEffects/yollum.ts
function isCore(state, cardDb, instance) {
  return effectiveRegions(state, cardDb, instance).includes(regionForTargetFilter(state, ashioAdjustedRegion(state, cardDb, "Core", ["Cald"])));
}
registerCardEffect("Yollum", {
  powerTargets: (state, cardDb) => [...allCreaturesInPlay(state, cardDb), ...allMagiInPlay(state)].filter((c2) => isCore(state, cardDb, c2)),
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Incinerate") return;
    if (ctx.chosenTargetId === void 0) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isCore(ctx.state, ctx.cardDb, target)) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 6, void 0, void 0, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment. Only covers the "Incinerate" ability's target pool;
  // the "Resistance" ability's blocksPowerEffectBySourceRegion hook below is unrelated and
  // untouched.
  specifiedTargetRegions: (state, cardDb) => [ashioAdjustedRegion(state, cardDb, "Core", ["Cald"])],
  blocksPowerEffectBySourceRegion: (state, cardDb) => {
    if (state.currentAction?.source !== "power" && state.currentAction?.source !== "spell") return false;
    const sourceKey = state.currentAction.sourceDefinitionKey;
    if (sourceKey === void 0) return false;
    const sourceDef = cardDb.get(sourceKey);
    if (!sourceDef) return false;
    return sourceDef.regions.includes(ashioAdjustedRegion(state, cardDb, "Core", ["Cald"]));
  }
});

// src/cardEffects/tlok.ts
function hasNoCreatures(state, cardDb, controllerId) {
  const player = state.players.get(controllerId);
  return !player || player.inPlay.every((c2) => cardDb.get(c2.definitionKey)?.card_type !== "Creature");
}
registerCardEffect("T'lok", {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn (naturalType 'Magi', alternate
  // Creature). Note a Crown-granted Creature target would always fail hasNoCreatures below (the
  // target itself is one of its controller's in-play Creatures), so this is correct but never
  // actually reachable -- same "harmless" shape as Kwup's STALKED tag.
  powerTargets: (state, cardDb, playerId) => flexibleTargetPool(state, cardDb, playerId, allMagiInPlay(state), allCreaturesInPlay(state, cardDb)).filter(
    (m) => hasNoCreatures(state, cardDb, m.controllerId)
  ),
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Big Ol' Rock") return;
    if (ctx.chosenTargetId === void 0) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, "Magi")) return;
    if (!hasNoCreatures(ctx.state, ctx.cardDb, target.controllerId)) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 10, void 0, void 0, ctx.rng);
  }
});

