// src/cardEffects/ookamisDrums.ts
function isBelowStarting(state, cardDb, c2) {
  return (c2.currentEnergy ?? 0) < effectiveStartingEnergy(state, cardDb, c2);
}
registerCardEffect("Ookami's Drums", {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn -- Badumbum only (it discards
  // energy); Badum adds energy, Dreamburn doesn't cover it, stays untouched.
  powerTargets: (state, cardDb, playerId, powerName) => {
    const naturalPool = allCreaturesInPlay(state, cardDb).filter((c2) => isBelowStarting(state, cardDb, c2));
    if (powerName !== "Badumbum") return naturalPool;
    const alternatePool = allMagiInPlay(state).filter((c2) => isBelowStarting(state, cardDb, c2));
    return flexibleTargetPool(state, cardDb, playerId, naturalPool, alternatePool);
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Badum" && ctx.powerName !== "Badumbum") return;
    if (ctx.chosenTargetId === void 0) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isBelowStarting(ctx.state, ctx.cardDb, target)) return;
    if (ctx.powerName === "Badum") {
      if (ctx.cardDb.get(target.definitionKey)?.card_type !== "Creature") return;
      addEnergy(ctx.state, ctx.cardDb, target, 1, "power");
    } else {
      if (!isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, "Creature")) return;
      discardEnergy(ctx.state, ctx.cardDb, target, 1, void 0, void 0, ctx.rng);
    }
  }
});

