// src/cardEffects/olum.ts
registerCardEffect("Olum", {
  // "Strengthen: When you play Olum, add one energy to each OTHER Olum in play." BUILT 2026-07-28
  // (ability-count sweep) -- the file had only Aid. Note the scope difference from Aid just below:
  // Aid says "each Olum in play" (this engine reads the garbled OCR as unrestricted, self included
  // -- though Aid discards Olum first anyway), while Strengthen says "each other Olum", so self is
  // excluded here explicitly.
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    for (const creature of allCreaturesInPlay(state, cardDb)) {
      if (creature.instanceId === self.instanceId) continue;
      if (cardDb.get(creature.definitionKey)?.name.includes("Olum")) {
        addEnergy(state, cardDb, creature, 1, "effect");
      }
    }
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Aid") return;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, void 0, void 0, ctx.rng);
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (ctx.cardDb.get(creature.definitionKey)?.name.includes("Olum")) {
        addEnergy(ctx.state, ctx.cardDb, creature, 1, "power");
      }
    }
  }
});

