function relicCount(state, cardDb, playerId) {
  return inPlayControlledBy(state, playerId).filter((c2) => cardDb.get(c2.definitionKey)?.card_type === "Relic").length;
}
registerCardEffect("Pearl Hyren", {
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Jealousy") return;
    const ownRelics2 = relicCount(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId);
    if (ownRelics2 === 0) return;
    const opponents = getOpponents(ctx.state, ctx.controllingPlayer.playerId);
    const opponentHasMore = opponents.some((p) => relicCount(ctx.state, ctx.cardDb, p.playerId) > ownRelics2);
    if (!opponentHasMore) return;
    for (const creature of creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      addEnergy(ctx.state, ctx.cardDb, creature, 1, "power");
    }
  },
  onOwnRelicChosenAsTargetByOpponent: (state, cardDb, self, chosenRelic, actorPlayerId) => {
    const actor = state.players.get(actorPlayerId);
    if (actor?.activeMagi) discardEnergy(state, cardDb, actor.activeMagi, 1, "effect", self.controllerId);
  }
});

