var GROLL_LINKED = "grollLinked";
registerCardEffect("Groll the Fallen", {
  onAttack: (ctx, self) => {
    if (ctx.defender === null) return;
    const isCore2 = (c2) => effectiveRegions(ctx.state, ctx.cardDb, c2).includes("Core");
    if (ctx.attacker.controllerId === self.controllerId && isCore2(ctx.defender)) {
      ctx.locked.defenderEnergy += 1;
    } else if (ctx.defender.controllerId === self.controllerId && isCore2(ctx.attacker)) {
      ctx.locked.attackerEnergy += 1;
    }
  },
  powerTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Desperate") return;
    if (ctx.chosenTargetId === void 0) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== "Creature") return;
    addDurationTag(ctx.state, ctx.cardDb, target, GROLL_LINKED, nextOwnTurnNumber(ctx.state) - 1);
  },
  afterCombat: (ctx, outcome, self) => {
    if (!hasDurationTag(ctx.attacker, GROLL_LINKED)) return;
    if (ctx.defender === null) return;
    const actualRemoved = outcome.defenderEnergyLost;
    if (actualRemoved > 0) addEnergy(ctx.state, ctx.cardDb, self, actualRemoved, "effect");
  }
});

