// src/cardEffects/sandsinger.ts
registerCardEffect("Sandsinger", {
  deckSearch: {
    count: 1,
    filter: (state, cardDb, playerId, card) => cardDb.get(card.definitionKey)?.regions.includes(regionForTargetFilter(state, "d'Resh")) ?? false
  },
  // Excludes itself at the POOL level (via sourceInstanceId, same fix as Flame Rudwot's Healing
  // Flame -- see registry.ts's powerTargets doc comment) -- this comment used to say that
  // information wasn't available at this stage, which was true before that 2026-07-08 fix but is
  // stale now; updated 2026-07-09 after the same class of bug was caught again in playtesting.
  powerTargets: (state, cardDb, playerId, powerName, sourceInstanceId) => inPlayControlledBy(state, playerId).filter((c2) => c2.instanceId !== sourceInstanceId),
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Ballad of the Truth") return;
    if (ctx.chosenTargetId === void 0) return;
    if (ctx.chosenTargetId === ctx.source.instanceId) return;
    const other = ctx.controllingPlayer.inPlay.find((c2) => c2.instanceId === ctx.chosenTargetId);
    if (!other) return;
    const ids = ctx.chosenDeckSearchIds ?? [];
    if (ids.length > 1) return;
    for (const id of ids) {
      const card = ctx.controllingPlayer.deck.find((c2) => c2.instanceId === id);
      if (!card || !ctx.cardDb.get(card.definitionKey)?.regions.includes(regionForTargetFilter(ctx.state, "d'Resh"))) return;
    }
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, ctx.source.instanceId, void 0, void 0, ctx.rng);
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, other.instanceId, void 0, void 0, ctx.rng);
    searchDeck(ctx.state, ctx.controllingPlayer, ids, ctx.rng);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ["d'Resh"]
});

// src/cardEffects/ythra.ts
var CLARITY_USED_THIS_TURN = "ythraClarityUsedThisTurn";
registerCardEffect("Ythra", {
  // Per-Effect hook narrowing (E1, 2026-08-12). Clarity is the on-own-draw reveal-and-draw;
  // Prodigy owns the d'Resh-Spell cost discount plus the unreducible-loss guard on d'Resh Spells.
  effectHooks: {
    Clarity: ["afterOwnDraw"],
    Prodigy: ["costModifier", "grantsUnreducibleEnergyLoss"]
  },
  afterOwnDraw: (state, cardDb, self, rng, drawn) => {
    if (hasDurationTag(self, CLARITY_USED_THIS_TURN)) return;
    const drewDreshSpell = drawn.some((c2) => {
      const def = cardDb.get(c2.definitionKey);
      return def?.card_type === "Spell" && def.regions.includes("d'Resh");
    });
    if (!drewDreshSpell) return;
    addDurationTag(state, cardDb, self, CLARITY_USED_THIS_TURN, state.turnNumber);
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    drawCards(state, cardDb, owner, 1);
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    if (playedDef.card_type !== "Spell") return 0;
    if (!playedDef.regions.includes("d'Resh")) return 0;
    return -1;
  },
  grantsUnreducibleEnergyLoss: (state, cardDb, self, ctx) => {
    if (ctx.scope !== "general" || ctx.cause !== "spell") return false;
    if (state.currentAction?.source !== "spell" || state.currentAction.actorPlayerId !== self.controllerId) return false;
    const sourceKey = state.currentAction.sourceDefinitionKey;
    const sourceDef = sourceKey !== void 0 ? cardDb.get(sourceKey) : void 0;
    return !!sourceDef?.regions.includes("d'Resh");
  }
});

