var AWAITING_CHOICE2 = "cloudOrshaaAwaitingChoice";
function eligibleSpells(state, cardDb, self) {
  const player = state.players.get(self.controllerId);
  if (!player) return [];
  return player.hand.filter((c2) => {
    const def = cardDb.get(c2.definitionKey);
    return def?.card_type === "Spell" && def.regions?.includes("Arderial");
  });
}
registerCardEffect("Cloud Orshaa", {
  onPlay: (state, cardDb, played, self) => {
    if (played.instanceId !== self.instanceId) return;
    if (eligibleSpells(state, cardDb, self).length === 0) return;
    addPendingChoiceTag(self, AWAITING_CHOICE2);
  },
  pendingMultiTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(AWAITING_CHOICE2)) return void 0;
    const eligible4 = eligibleSpells(state, cardDb, self);
    if (eligible4.length === 0) return void 0;
    return {
      prompt: "Cloud Orshaa's Mystic Binding: discard up to four Arderial Spells from your hand (add two energy to Cloud Orshaa for each)",
      pool: eligible4.map((c2) => c2.instanceId),
      minCount: 0,
      maxCount: Math.min(4, eligible4.length)
    };
  },
  resolveMultiTargetChoice: (state, cardDb, self, chosenInstanceIds, rng) => {
    removePermanentTag(self, AWAITING_CHOICE2);
    const player = state.players.get(self.controllerId);
    if (!player) return;
    const eligible4 = eligibleSpells(state, cardDb, self);
    const eligibleIds = new Set(eligible4.map((c2) => c2.instanceId));
    let chosen;
    if (chosenInstanceIds) {
      const ids = [...new Set(chosenInstanceIds)].filter((id) => eligibleIds.has(id)).slice(0, 4);
      chosen = ids.map((id) => eligible4.find((c2) => c2.instanceId === id)).filter((c2) => c2 !== void 0);
    } else {
      chosen = eligible4.slice(0, 4);
    }
    for (const card of chosen) {
      const index = player.hand.findIndex((c2) => c2.instanceId === card.instanceId);
      if (index === -1) continue;
      player.hand.splice(index, 1);
      moveToDiscardPile(state, player, card);
    }
    if (chosen.length > 0) {
      addEnergy(state, cardDb, self, chosen.length * 2, "effect");
    }
    checkHandEmptied(state, cardDb, rng);
  }
});

