    if (playedDef.regions.includes("Naroom") && !hasDurationTag(self, FOREST_POWER_USED_THIS_TURN)) {
      const magi = state.players.get(self.controllerId)?.activeMagi;
      if (magi) {
        addEnergy(state, cardDb, magi, 2, "effect");
        addDurationTag(state, cardDb, self, FOREST_POWER_USED_THIS_TURN, state.turnNumber);
      }
    }
