registerCardEffect("Yricho's Staff", {
  // The Safe Effect is still declared here so effectHooks lookup for lockdown ('Rayje-Belt lock
  // of Safe' silences this card's participation in `findEligibleYrichoCandidatesForDiscard`)
  // continues to work. No runtime hooks -- the mechanism lives in effects.ts + this file's
  // consumer, same external-suppression pattern as Vault of Knowledge Key's Archive.
  effectHooks: { Safe: [] }
});
registerRollConsumer("yrichoStaff:safe", (state, cardDb, _source, payload, finalRoll, rng) => {
  const { ownerId } = payload;
  const pending = state.pendingDiscardFromPlay;
  if (!pending || pending.ownerId !== ownerId) {
    state.pendingDiscardFromPlay = null;
    drainPendingDiscardQueue(state, cardDb, rng);
    return;
  }
  const owner = state.players.get(pending.ownerId);
  const magi = owner?.activeMagi;
  const magiEnergy = magi?.currentEnergy ?? 0;
  if (magi && finalRoll < magiEnergy) {
    discardEnergy(state, cardDb, magi, 2, "effect");
    state.pendingDiscardFromPlay = null;
    drainPendingDiscardQueue(state, cardDb, rng);
    return;
  }
  const remaining = pending.remainingYrichoCandidateInstanceIds;
  if (remaining.length > 0) {
    const nextInstanceId = remaining[0];
    const nextYricho = owner?.inPlay.find((c2) => c2.instanceId === nextInstanceId);
    if (nextYricho) {
      state.pendingDiscardFromPlay = {
        ...pending,
        remainingYrichoCandidateInstanceIds: remaining.slice(1)
      };
      requestDieRoll(
        state,
        cardDb,
        nextYricho,
        pending.ownerId,
        6,
        "yrichoStaff:safe",
        { yrichoStaffInstanceId: nextYricho.instanceId, ownerId: pending.ownerId, targetInstanceId: pending.targetInstanceId },
        rng
      );
      return;
    }
  }
  const snapshot = pending;
  state.pendingDiscardFromPlay = null;
  resumeDiscardFromPlay(state, cardDb, snapshot, rng);
  drainPendingDiscardQueue(state, cardDb, rng);
});

