var SHATTER_PENDING = "aegrisShatterPending";
registerCardEffect("Aegris", {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Bypass is the frozen-attack-Magi
  // allowance; Shatter is the whenever-attacks-a-Magi discard-a-Creature sequence.
  effectHooks: {
    Bypass: ["canAttackMagiDirectly"],
    Shatter: ["afterCombat", "pendingTargetChoice", "resolveTargetChoice"]
  },
  canAttackMagiDirectly: (state, cardDb, instance) => isFrozen(state, cardDb, instance),
  afterCombat: (ctx, outcome, self) => {
    if (ctx.attacker.instanceId !== self.instanceId) return;
    if (ctx.defender !== null) return;
    const hasTarget = ctx.defendingPlayer.inPlay.some((c2) => ctx.cardDb.get(c2.definitionKey)?.card_type === "Creature");
    if (!hasTarget) return;
    addPendingChoiceTag(self, SHATTER_PENDING);
    discardFromPlay(ctx.state, ctx.cardDb, ctx.attackingPlayer, self.instanceId, void 0, void 0, ctx.rng);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(SHATTER_PENDING)) return void 0;
    const pool3 = opposingCreatures(state, cardDb, self.controllerId);
    if (pool3.length === 0) return void 0;
    return { prompt: "Aegris's Shatter: choose one of that Magi's Creatures to discard from play", pool: pool3 };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, SHATTER_PENDING);
    if (!chosenInstanceId) return;
    const target = opposingCreatures(state, cardDb, self.controllerId).find((c2) => c2.instanceId === chosenInstanceId);
    if (!target) return;
    const owner = state.players.get(target.controllerId);
    if (owner) discardFromPlay(state, cardDb, owner, target.instanceId, void 0, void 0, rng);
  }
});

