// src/cardEffects/hajnyn.ts
registerCardEffect("Hajnyn", {
  powerTargetSlots: (state, cardDb, playerId) => [
    {
      label: "Choose a Frozen Creature you control",
      pool: (s, db, pid) => creaturesControlledBy(s, db, pid).filter((c2) => isFrozen(s, db, c2)),
      min: 1,
      max: 1
    },
    {
      label: "Choose an opposing Creature with less energy",
      pool: (s, db, pid, priorChoices) => {
        const chosenId = priorChoices[0]?.[0];
        if (!chosenId) return [];
        const chosen = findInPlayById(s, chosenId);
        if (!chosen) return [];
        return opposingCreatures(s, db, pid).filter((c2) => (c2.currentEnergy ?? 0) < (chosen.currentEnergy ?? 0));
      },
      min: 1,
      max: 1
    }
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Iceberg") return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const ownTargetId = slots[0]?.[0];
    const oppTargetId = slots[1]?.[0];
    if (!ownTargetId || !oppTargetId) return;
    const ownTarget = findInPlayById(ctx.state, ownTargetId);
    if (!ownTarget || ctx.cardDb.get(ownTarget.definitionKey)?.card_type !== "Creature") return;
    if (ownTarget.controllerId !== ctx.controllingPlayer.playerId) return;
    if (!isFrozen(ctx.state, ctx.cardDb, ownTarget)) return;
    const oppTarget = findInPlayById(ctx.state, oppTargetId);
    if (!oppTarget || ctx.cardDb.get(oppTarget.definitionKey)?.card_type !== "Creature") return;
    if (oppTarget.controllerId === ctx.controllingPlayer.playerId) return;
    if ((oppTarget.currentEnergy ?? 0) >= (ownTarget.currentEnergy ?? 0)) return;
    const ownController = ctx.controllingPlayer;
    const oppController = ctx.state.players.get(oppTarget.controllerId);
    if (!oppController) return;
    discardFromPlay(ctx.state, ctx.cardDb, ownController, ownTarget.instanceId, void 0, void 0, ctx.rng);
    discardFromPlay(ctx.state, ctx.cardDb, oppController, oppTarget.instanceId, void 0, void 0, ctx.rng);
  }
});

// src/cardEffects/syre.ts
registerCardEffect("Syre", {
  // task #34, 2026-07-16: widened for Abraxin's Crown's Dreamburn. Magi are never burrowed in
  // this engine, so a Crown-granted Magi option would always fail the isBurrowed check below,
  // harmlessly (same "correct but never actually reachable" shape as Kwup's STALKED tag).
  powerTargets: (state, cardDb, playerId) => {
    const ownMagi = state.players.get(playerId)?.activeMagi;
    return flexibleTargetPool(state, cardDb, playerId, creaturesControlledBy(state, cardDb, playerId), ownMagi ? [ownMagi] : []).filter(
      (c2) => isBurrowed(state, cardDb, c2)
    );
  },
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Undream Tap") return;
    if (ctx.chosenTargetId === void 0) return;
    const target = findCreatureOrMagiById(ctx.state, ctx.chosenTargetId);
    if (!target || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, target, "Creature")) return;
    if (target.controllerId !== ctx.controllingPlayer.playerId) return;
    if (!isBurrowed(ctx.state, ctx.cardDb, target)) return;
    discardEnergy(ctx.state, ctx.cardDb, target, 1, void 0, void 0, ctx.rng);
    drawCards(ctx.state, ctx.cardDb, ctx.controllingPlayer, 1);
  }
});

