// src/cardEffects/purityRing.ts
function applyPurity(state, cardDb, self, region, rng) {
  const player = state.players.get(self.controllerId);
  if (!player) return false;
  const spellsInDiscard = player.discardPile.filter((c2) => cardDb.get(c2.definitionKey)?.card_type === "Spell");
  const allMatchRegion = spellsInDiscard.every((c2) => effectiveRegions(state, cardDb, c2).includes(region));
  if (!allMatchRegion) return false;
  const nonRegion = inPlayControlledBy(state, self.controllerId).filter(
    (c2) => !effectiveRegions(state, cardDb, c2).includes(region)
  );
  for (const card of nonRegion) {
    discardFromPlay(state, cardDb, player, card.instanceId, void 0, void 0, rng);
  }
  return true;
}

// src/cardEffects/stragsRing.ts
var PURITY_PENDING = "stragsRingPurityPending";
registerCardEffect("Strag's Ring", {
  onOwnTurnEnd: (state, cardDb, self, rng) => {
    if (!applyPurity(state, cardDb, self, "Underneath", rng)) return;
    if (allCreaturesInPlay(state, cardDb).length === 0) return;
    addPendingChoiceTag(self, PURITY_PENDING);
  },
  pendingTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(PURITY_PENDING)) return void 0;
    const pool3 = allCreaturesInPlay(state, cardDb);
    if (pool3.length === 0) return void 0;
    return { prompt: "Strag's Ring's Purity: choose a Creature to make burrowed until the end of your next turn", pool: pool3 };
  },
  resolveTargetChoice: (state, cardDb, self, chosenInstanceId, rng) => {
    removePermanentTag(self, PURITY_PENDING);
    if (!chosenInstanceId) return;
    const target = allCreaturesInPlay(state, cardDb).find((c2) => c2.instanceId === chosenInstanceId);
    if (target) applyBurrowedTag(state, cardDb, target, nextOwnTurnNumber(state), self.instanceId, rng);
  }
});

// src/cardEffects/djarvish.ts
registerCardEffect("d'Jarvish", {
  // Per-Effect hook narrowing (E1, 2026-08-12). Strengthen owns the end-of-turn +1 to burrowed/
  // illusion attackers; Escape owns the hand-return-on-opponent-discard reaction.
  effectHooks: {
    Strengthen: ["onOwnTurnEnd"],
    Escape: ["onCardDiscardedFromPlay"]
  },
  onOwnTurnEnd: (state, cardDb, self) => {
    const own = creaturesControlledBy(state, cardDb, self.controllerId);
    for (const creature of own) {
      if (!creature.attackedThisTurn) continue;
      if (!isBurrowed(state, cardDb, creature) && !isIllusion(creature)) continue;
      addEnergy(state, cardDb, creature, 1, "effect");
    }
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self, cause, source, causedByPlayerId) => {
    if (discardedOwnerId !== self.controllerId) return;
    if (cause !== "explicit") return;
    if (causedByPlayerId === void 0 || causedByPlayerId === self.controllerId) return;
    if (!isBurrowed(state, cardDb, discarded) && !isIllusion(discarded)) return;
    const owner = state.players.get(discardedOwnerId);
    if (!owner) return;
    const card = removeFromZone(owner, "discardPile", discarded.instanceId);
    addToZone(owner, "hand", card);
  }
});

