// src/cardEffects/tKanzam.ts
registerCardEffect("T'kanzam", {
  // Per-Effect hook narrowing (C3 Q2, 2026-08-12: Taglat). Dreamwarp is the standard self-play
  // data field; Dream Loops pairs the eager copied-Power grant with the actual reaction check
  // (same reactive-window shape as Yricho/Bazha's Pendant).
  effectHooks: {
    Dreamwarp: ["dreamwarpRange"],
    "Dream Loops": ["prepareReactionToWindow", "reactsToWindow"]
  },
  dreamwarpRange: () => 1,
  prepareReactionToWindow: (state, cardDb, window, self) => {
    if (window.kind !== "opponentPlayOrPower" || window.trigger !== "power") return;
    if (!window.powerSourceIsCreature) return;
    if (window.reactingPlayerId !== self.controllerId) return;
    if (!window.powerSourceInstanceId || !window.powerName) return;
    const sourceCard = findInPlayById(state, window.powerSourceInstanceId);
    if (!sourceCard) return;
    const sourceDef = cardDb.get(sourceCard.definitionKey);
    const originalPower = sourceDef?.powers.find((p) => p.name === window.powerName);
    if (!sourceDef || !originalPower) return;
    addCopiedPower(self, originalPower, sourceDef.key, { afterTurnNumber: state.turnNumber });
  },
  // Not actually vulnerable to the bazhasPendant.ts/yricho.ts hand-copy bug (activeCopiedPowers is
  // per-CardInstance-object, and prepareReactionToWindow only ever grants the copy onto the genuine
  // in-play instance, never a hand copy) -- the explicit in-play check is just cheap, consistent
  // insurance matching the other two reactsToWindow users of this same window kind.
  reactsToWindow: (state, cardDb, window, playerId, self) => {
    if (window.kind !== "opponentPlayOrPower" || window.trigger !== "power") return false;
    if (window.reactingPlayerId !== playerId) return false;
    if (self.controllerId !== playerId) return false;
    if (!findInPlayById(state, self.instanceId)) return false;
    return activeCopiedPowers(state, self).some((cp) => cp.power.name === window.powerName);
  }
});

// src/cardEffects/yricho.ts
var USED_THIS_TURN5 = "yrichoAthleticUsedThisTurn";
registerCardEffect("Yricho", {
  // See bazhasPendant.ts's matching comment: reactsToWindow is ALSO checked by play.ts's
  // isLegalToPlay against every card sitting in the reacting player's hand (Rabid Wasperine's
  // original use case) -- Athletic only ever means "use a Power on one of your in-play cards,"
  // never "play Yricho itself from hand," so a hand copy must not qualify. Yricho is a MAGI, so the
  // in-play check has to cover activeMagi too, not just inPlay (findInPlayById alone would wrongly
  // reject the real, currently-active Yricho -- caught by the existing test suite).
  reactsToWindow: (state, cardDb, window, playerId, self) => {
    if (window.kind !== "opponentPlayOrPower" || window.trigger !== "power") return false;
    if (window.reactingPlayerId !== playerId) return false;
    if (self.controllerId !== playerId) return false;
    if (!findCreatureOrMagiById(state, self.instanceId)) return false;
    if (hasDurationTag(self, USED_THIS_TURN5)) return false;
    return true;
  },
  confirmReactionToWindow: (state, cardDb, window, playerId, self) => {
    addDurationTag(state, cardDb, self, USED_THIS_TURN5, state.turnNumber);
  }
});

// src/cardEffects/bazhasPendant.ts
var USED_THIS_TURN6 = "bazhasPendantReplyUsedThisTurn";
registerCardEffect("Bazha's Pendant", {
  // reactsToWindow is checked from TWO different places: power.ts's isLegalPowerUse (broadcasting
  // over the reacting player's whole in-play board, to see if THIS in-play card grants a reactive
  // Power use elsewhere) AND play.ts's isLegalToPlay (checking the SAME hook against every card
  // sitting in the reacting player's HAND, to see if that hand card itself can be played
  // reactively -- Rabid Wasperine's original use case). Reply only ever means the FIRST thing --
  // "use a Power on one of your in-play cards" -- never "play Bazha's Pendant itself from hand." A
  // hand copy trivially passes controllerId/duration-tag checks too, so without this explicit
  // in-play check it was incorrectly showing up as reactively PLAYABLE (live playtest, 2026-07-19,
  // exposed once Spells started opening real opponentPlayOrPower windows).
  reactsToWindow: (state, cardDb, window, playerId, self) => {
    if (window.kind !== "opponentPlayOrPower") return false;
    if (window.reactingPlayerId !== playerId) return false;
    if (self.controllerId !== playerId) return false;
    if (!findInPlayById(state, self.instanceId)) return false;
    if (hasDurationTag(self, USED_THIS_TURN6)) return false;
    return true;
  },
  confirmReactionToWindow: (state, cardDb, window, playerId, self) => {
    addDurationTag(state, cardDb, self, USED_THIS_TURN6, state.turnNumber);
  }
});

