// src/cardEffects/statementOfCoreValues.ts
var PLAYED_BOGRATH_THIS_TURN = "statementOfCoreValuesPlayedBograthThisTurn";
var PLAYED_CORE_THIS_TURN = "statementOfCoreValuesPlayedCoreThisTurn";
registerCardEffect("Statement of Core Values", {
  // Per-Effect hook narrowing (deep-dive audit, 2026-08-13). Both Buddies and Pals share the
  // onPlay tag setup + costModifier read; only the branch inside costModifier differs. Both
  // list the same hooks per the shared-body convention (Wandering Balamant's Fetch precedent),
  // with the onOwnTurnStart tag-clear folded under both. The Ashio-substitution simplification
  // that collapses Buddies into Pals is documented in the header above.
  effectHooks: {
    Buddies: ["onOwnTurnStart", "onPlay", "costModifier"],
    Pals: ["onOwnTurnStart", "onPlay", "costModifier"]
  },
  onOwnTurnStart: (state, cardDb, self) => {
    removePermanentTag(self, PLAYED_BOGRATH_THIS_TURN);
    removePermanentTag(self, PLAYED_CORE_THIS_TURN);
  },
  onPlay: (state, cardDb, played, self) => {
    if (played.controllerId !== self.controllerId) return;
    const regions = cardDb.get(played.definitionKey)?.regions ?? [];
    const ashioCore = ashioAdjustedRegion(state, cardDb, "Core", ["Bograth", "Core"]);
    if (regions.includes("Bograth")) addPermanentTag(state, cardDb, self, PLAYED_BOGRATH_THIS_TURN);
    if (regions.includes(ashioCore)) addPermanentTag(state, cardDb, self, PLAYED_CORE_THIS_TURN);
  },
  costModifier: (state, cardDb, playedDef, playerId, self) => {
    if (playerId !== self.controllerId) return 0;
    const ashioCore = ashioAdjustedRegion(state, cardDb, "Core", ["Bograth", "Core"]);
    let delta = 0;
    if (playedDef.regions.includes(ashioCore) && self.tags.has(PLAYED_BOGRATH_THIS_TURN)) delta -= 1;
    if (playedDef.regions.includes("Bograth") && self.tags.has(PLAYED_CORE_THIS_TURN)) delta -= 1;
    return delta;
  }
});

