    const chosenIds = ctx.chosenSlotIds?.[0] ?? [];
    if (chosenIds.length === 0) return;
    const shuffledAwayId = ctx.chosenSlotIds?.[1]?.[0];
    if (shuffledAwayId) {
      const index = player.discardPile.findIndex((c2) => c2.instanceId === shuffledAwayId);
      if (index !== -1) {
        const [card] = player.discardPile.splice(index, 1);
        player.deck.push(card);
        for (let i = player.deck.length - 1; i > 0; i--) {
          const j = Math.floor(ctx.rng() * (i + 1));
          [player.deck[i], player.deck[j]] = [player.deck[j], player.deck[i]];
        }
      }
    }
    for (const id of chosenIds) {
      if (id === shuffledAwayId) continue;
      const played = playFromZone(ctx.state, ctx.cardDb, { owner: player, zone: "discardPile", instanceId: id }, player, 1, ctx.rng);
      if (played) addRestrictionTag(ctx.state, played, CANNOT_ATTACK, ctx.state.turnNumber);
    }
