    if (ctx.chosenSecondTargetId === void 0 || ctx.chosenSecondTargetId === ctx.chosenTargetId) return;
    const second = pool3.find((c2) => c2.instanceId === ctx.chosenSecondTargetId);
    if (second) restoreEnergy(ctx.state, ctx.cardDb, second, printedStartingEnergy(ctx.cardDb, second.definitionKey));
