// src/cardEffects/snare.ts
function magiIsNotParadwyn(state, cardDb, playerId) {
  const magi = state.players.get(playerId)?.activeMagi;
  if (!magi) return true;
  const def = cardDb.get(magi.definitionKey);
  if (!def) return true;
  return !effectiveMagiDef(def, magi).regions.includes(regionForTargetFilter(state, "Paradwyn"));
}
registerCardEffect("Snare", {
  reactsToWindow: (state, cardDb, window) => window.kind === "opponentAttackStepBegan",
  // "one of THAT PLAYER's Creatures" -- the active player whose Attack step just began. Derived
  // from the live window rather than getOpponents so the pool can never disagree with the window
  // that legalized the play.
  spellTargets: (state, cardDb, playerId) => {
    const window = state.reactiveWindow;
    const targetPlayerId = window?.kind === "opponentAttackStepBegan" ? window.actingPlayerId : void 0;
    if (targetPlayerId === void 0 || targetPlayerId === playerId) return [];
    return [...state.players.get(targetPlayerId)?.inPlay ?? []];
  },
  spellHandDiscardCost: { count: 1, condition: magiIsNotParadwyn },
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === void 0) return;
    const window = ctx.state.reactiveWindow;
    const targetPlayerId = window?.kind === "opponentAttackStepBegan" ? window.actingPlayerId : void 0;
    if (targetPlayerId === void 0 || targetPlayerId === ctx.controllingPlayer.playerId) return;
    const target = ctx.state.players.get(targetPlayerId)?.inPlay.find((c2) => c2.instanceId === ctx.chosenTargetId);
    if (!target) return;
    addRestrictionTag(ctx.state, target, CANNOT_ATTACK, ctx.state.turnNumber);
    if (magiIsNotParadwyn(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId)) {
      const ids = ctx.chosenHandCardIds ?? [];
      if (ids.length === 1) discardFromHand(ctx.state, ctx.cardDb, ctx.controllingPlayer, ids, void 0, ctx.rng);
      checkHandEmptied(ctx.state, ctx.cardDb, ctx.rng);
    }
  }
});

