registerRollConsumer("groundBreaker:resolve", (state, cardDb, _source, payload, finalRoll, rng) => {
  const { chosenTargetId, controllingPlayerId } = payload;
  const target = allMagiInPlay(state).find((m) => m.instanceId === chosenTargetId);
  if (!target) return;
  discardEnergy(state, cardDb, target, finalRoll, "spell", controllingPlayerId, rng);
});

// src/cardEffects/carnivorousCave.ts
registerCardEffect("Carnivorous Cave", {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- unconditional (no region/burrow
  // exemption applies to a Magi), so this only checks that an opposing Magi actually exists.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId) => getOpponents(state, actingPlayerId).some((opp) => !!opp.activeMagi),
  resolveSpell: (ctx) => {
    const casterId = ctx.controllingPlayer.playerId;
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      if (isBurrowed(ctx.state, ctx.cardDb, creature)) continue;
      discardEnergy(ctx.state, ctx.cardDb, creature, 1, "spell", casterId, ctx.rng);
    }
    for (const magi of allMagiInPlay(ctx.state)) {
      discardEnergy(ctx.state, ctx.cardDb, magi, 1, "spell", casterId, ctx.rng);
    }
  }
});

// src/cardEffects/caveIn.ts
function magiRegions(cardDb, magi) {
  const def = cardDb.get(magi.definitionKey);
  return def ? effectiveMagiDef(def, magi).regions : [];
}
registerCardEffect("Cave In", {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- static region check mirroring
  // resolveSpell's own two-clause gating below, no execution.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId) => {
    const underneath = regionForTargetFilter(state, "Underneath");
    const arderial = regionForTargetFilter(state, "Arderial");
    return getOpponents(state, actingPlayerId).some((opp) => {
      if (!opp.activeMagi) return false;
      const regions = magiRegions(cardDb, opp.activeMagi);
      return !regions.includes(underneath) || regions.includes(arderial);
    });
  },
  resolveSpell: (ctx) => {
    const casterId = ctx.controllingPlayer.playerId;
    const underneath = regionForTargetFilter(ctx.state, "Underneath");
    const arderial = regionForTargetFilter(ctx.state, "Arderial");
    for (const creature of allCreaturesInPlay(ctx.state, ctx.cardDb)) {
      const regions = effectiveRegions(ctx.state, ctx.cardDb, creature);
      if (!regions.includes(underneath)) discardEnergy(ctx.state, ctx.cardDb, creature, 1, "spell", casterId, ctx.rng);
      if (regions.includes(arderial)) discardEnergy(ctx.state, ctx.cardDb, creature, 1, "spell", casterId, ctx.rng);
    }
    for (const magi of allMagiInPlay(ctx.state)) {
      const regions = magiRegions(ctx.cardDb, magi);
      if (!regions.includes(underneath)) discardEnergy(ctx.state, ctx.cardDb, magi, 1, "spell", casterId, ctx.rng);
      if (regions.includes(arderial)) discardEnergy(ctx.state, ctx.cardDb, magi, 1, "spell", casterId, ctx.rng);
    }
  }
});

