// src/cardEffects/iceRupture.ts
registerCardEffect("Ice Rupture", {
  // Three-Leaf Clover's Lotta Lucky (bug fix 2026-08-09) -- reads the already-chosen chain
  // (own frozen Creature -> opposing Magi) the same way resolveSpell does, including the
  // amount > 0 gate (a 0-energy frozen Creature deals no damage), no execution.
  hitsOpposingMagi: (state, cardDb, self, actingPlayerId, options) => {
    const ownId = options.chosenTargetId;
    const magiId = options.chosenSecondTargetId;
    if (!ownId || !magiId) return false;
    const own = creaturesControlledBy(state, cardDb, actingPlayerId).find((c2) => c2.instanceId === ownId);
    if (!own || (own.currentEnergy ?? 0) <= 0) return false;
    const magi = allMagiInPlay(state).find((m) => m.instanceId === magiId);
    return !!magi && magi.controllerId !== actingPlayerId;
  },
  spellTargets: (state, cardDb, playerId) => creaturesControlledBy(state, cardDb, playerId).filter(
    // In-play Creature check -- routes through effectiveRegions so Glablit's Dream Blur
    // (Category D EIGHTH item, 2026-08-12, task #725) applies.
    (c2) => isFrozen(state, cardDb, c2) && effectiveRegions(state, cardDb, c2).includes(regionForTargetFilter(state, "Nar"))
  ),
  spellSecondTargets: (state, cardDb, playerId) => {
    const opponentIds = new Set(getOpponents(state, playerId).map((p) => p.playerId));
    return allMagiInPlay(state).filter((m) => opponentIds.has(m.controllerId));
  },
  spellThirdTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId, secondChosenId) => {
    const magi = allMagiInPlay(state).find((m) => m.instanceId === secondChosenId);
    if (!magi) return [];
    return creaturesControlledBy(state, cardDb, magi.controllerId);
  },
  resolveSpell: (ctx) => {
    const own = creaturesControlledBy(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId).find(
      (c2) => c2.instanceId === ctx.chosenTargetId
    );
    const magi = allMagiInPlay(ctx.state).find((m) => m.instanceId === ctx.chosenSecondTargetId);
    if (!own || !magi) return;
    const creature = creaturesControlledBy(ctx.state, ctx.cardDb, magi.controllerId).find(
      (c2) => c2.instanceId === ctx.chosenThirdTargetId
    );
    if (!creature) return;
    const amount = own.currentEnergy ?? 0;
    discardFromPlay(ctx.state, ctx.cardDb, ctx.controllingPlayer, own.instanceId, void 0, "spell", ctx.rng);
    if (amount > 0) {
      discardEnergy(ctx.state, ctx.cardDb, magi, amount, "spell", void 0, ctx.rng);
      discardEnergy(ctx.state, ctx.cardDb, creature, amount, "spell", void 0, ctx.rng);
    }
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedSpellTargetRegions: () => ["Nar"]
});

// src/cardEffects/naranLights.ts
registerCardEffect("Naran Lights", {
  spellTargets: (state, cardDb, playerId) => {
    const player = state.players.get(playerId);
    if (!player) return [];
    return player.deck.slice(0, 3).filter((c2) => cardDb.get(c2.definitionKey)?.subtype === "Arctic" && effectiveCardType(cardDb, c2) === "Creature");
  },
  resolveSpell: (ctx) => {
    const player = ctx.controllingPlayer;
    const revealed = player.deck.slice(0, 3);
    const chosen = ctx.chosenTargetId ? revealed.find((c2) => c2.instanceId === ctx.chosenTargetId) : void 0;
    if (chosen) {
      searchDeckIntoPlay(ctx.state, ctx.cardDb, player, chosen.instanceId, 5, true, ctx.rng);
      for (const card of revealed) {
        if (card.instanceId === chosen.instanceId) continue;
        const index = player.deck.findIndex((c2) => c2.instanceId === card.instanceId);
        if (index !== -1) {
          const [removed] = player.deck.splice(index, 1);
          addToZone(player, "deck", removed, "bottom");
        }
      }
      checkCreatureDefeats(ctx.state, ctx.cardDb);
    } else {
      for (const card of revealed) {
        const index = player.deck.findIndex((c2) => c2.instanceId === card.instanceId);
        if (index !== -1) {
          const [removed] = player.deck.splice(index, 1);
          addToZone(player, "hand", removed);
        }
      }
    }
  }
});

// src/cardEffects/refract.ts
registerCardEffect("Refract", {
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    const magi = ctx.controllingPlayer.activeMagi;
    if (!magi) return;
    attachCard(magi, ctx.source);
  },
  offersTargetRedirect: (state, cardDb, self, targetedInstanceId) => {
    const target = findCreatureOrMagiById(state, targetedInstanceId);
    if (!target) return false;
    if (target.controllerId !== self.controllerId) return false;
    const targetDef = cardDb.get(target.definitionKey);
    return targetDef?.card_type === "Creature" && effectiveRegions(state, cardDb, target).includes(regionForTargetFilter(state, "Nar"));
  },
  redirectTargetPool: (state, cardDb, self) => (
    // In-play pool -- effectiveRegions honors Dream Blur (2026-08-12, task #725).
    creaturesControlledBy(state, cardDb, self.controllerId).filter((c2) => effectiveRegions(state, cardDb, c2).includes(regionForTargetFilter(state, "Nar")))
  ),
  resolveTargetRedirect: (state, cardDb, self) => {
    const magi = state.players.get(self.controllerId)?.activeMagi;
    if (!magi) return;
    const detached = detachCard(magi, self.instanceId);
    if (!detached) return;
    const owner = state.players.get(detached.ownerId);
    if (owner) moveToDiscardPile(state, owner, detached);
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ["Nar"]
});

