// src/cardEffects/tapRoots.ts
registerCardEffect("Tap Roots", {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb),
  spellSecondTargets: (state, cardDb, playerId, sourceInstanceId, firstChosenId) => allCreaturesInPlay(state, cardDb).filter((c2) => c2.instanceId !== firstChosenId),
  // Printed as two clauses ("Remove up to two energy from one... Add up to two energy to the
  // other"), but it is one transfer of a single amount -- the two numbers are the same move seen
  // from each end, so ONE choice, not two. Capped at the source's energy by resolveSpell.
  spellAmountChoices: () => [
    { id: "move", prompt: "Tap Roots: move how much energy between the chosen Creatures? (0-2)", min: 0, max: 2 }
  ],
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === void 0 || ctx.chosenSecondTargetId === void 0) return;
    if (ctx.chosenTargetId === ctx.chosenSecondTargetId) return;
    const from = findInPlayById(ctx.state, ctx.chosenTargetId);
    const to = findInPlayById(ctx.state, ctx.chosenSecondTargetId);
    if (!from || ctx.cardDb.get(from.definitionKey)?.card_type !== "Creature") return;
    if (!to || ctx.cardDb.get(to.definitionKey)?.card_type !== "Creature") return;
    const cap = Math.min(2, from.currentEnergy ?? 0);
    const amount = Math.max(0, Math.min(ctx.chosenAmounts?.["move"] ?? cap, cap));
    if (amount > 0) rearrangeEnergy(ctx.state, ctx.cardDb, from, to, amount, ctx.rng);
  }
});

