// src/cardEffects/sheath.ts
var HOST_PREFIX3 = "sheathHost:";
var DISCARD_PENDING2 = "sheathDiscardPending";
registerCardEffect("Sheath", {
  spellTargets: (state, cardDb) => allCreaturesInPlay(state, cardDb).filter(
    (c2) => effectiveRegions(state, cardDb, c2).includes(regionForTargetFilter(state, "Weave"))
  ),
  spellStaysInPlay: true,
  resolveSpell: (ctx) => {
    if (ctx.chosenTargetId === void 0) return;
    const target = findInPlayById(ctx.state, ctx.chosenTargetId);
    if (!target || ctx.cardDb.get(target.definitionKey)?.card_type !== "Creature") return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, target).includes(regionForTargetFilter(ctx.state, "Weave"))) return;
    addEnergy(ctx.state, ctx.cardDb, target, 8, "spell");
    addPermanentRestrictionTag(ctx.state, target, CANNOT_ATTACK);
    addPermanentRestrictionTag(ctx.state, target, CANNOT_USE_POWER);
    addPermanentRestrictionTag(ctx.state, target, EFFECTS_LOCKED_DOWN);
    addPermanentTag(ctx.state, ctx.cardDb, ctx.source, HOST_PREFIX3 + target.instanceId);
    attachCard(target, ctx.source);
  },
  onCardDiscardedFromPlay: (state, cardDb, discarded, discardedOwnerId, self) => {
    if (discarded.instanceId !== self.instanceId) return;
    let hostId;
    for (const tag of self.tags) if (tag.startsWith(HOST_PREFIX3)) hostId = tag.slice(HOST_PREFIX3.length);
    if (hostId === void 0 || !isInAnyDiscardPile(state, hostId)) return;
    removePermanentTag(self, HOST_PREFIX3 + hostId);
    const owner = state.players.get(self.controllerId);
    if (!owner || owner.hand.length === 0) return;
    addPendingChoiceTag(self, DISCARD_PENDING2);
  },
  pendingMultiTargetChoice: (state, cardDb, self) => {
    if (!self.tags.has(DISCARD_PENDING2)) return void 0;
    const owner = state.players.get(self.controllerId);
    const pool3 = (owner?.hand ?? []).map((c2) => c2.instanceId);
    if (pool3.length === 0) return void 0;
    const count = Math.min(2, pool3.length);
    return {
      prompt: "Sheath: choose two cards to discard from your hand",
      pool: pool3,
      minCount: count,
      maxCount: count
    };
  },
  resolveMultiTargetChoice: (state, cardDb, self, chosenInstanceIds, rng) => {
    if (!self.tags.has(DISCARD_PENDING2)) return;
    removePermanentTag(self, DISCARD_PENDING2);
    const owner = state.players.get(self.controllerId);
    if (!owner) return;
    const count = Math.min(2, owner.hand.length);
    const ids = (chosenInstanceIds ?? owner.hand.map((c2) => c2.instanceId)).filter((id) => owner.hand.some((c2) => c2.instanceId === id)).slice(0, count);
    if (ids.length > 0) discardFromHand(state, cardDb, owner, ids, void 0, rng);
  }
});

// src/cardEffects/scurryingWeggit.ts
var FORCED_ATTACK_OPTIONS = {
  ignoreActivePlayerGate: true,
  ignorePhaseGate: true,
  ignoreAttackRestrictions: true
};
registerCardEffect("Scurrying Weggit", {
  powerTargetSlots: () => [
    {
      // Abraxin's Crown's Dreamburn may widen this to accept a Magi (task #34) -- slot 1 feeds
      // discardEnergy, same as Slinking Greal's. A Magi picked that way just never reaches the
      // attack half below, which re-validates the target as a Creature.
      label: "Choose an opposing Weave Creature",
      pool: (s, db, pid) => flexibleTargetPool(s, db, pid, opposingCreatures(s, db, pid), opposingMagi(s, db, pid)).filter(
        (c2) => effectiveRegions(s, db, c2).includes(regionForTargetFilter(s, "Weave"))
      ),
      min: 1,
      max: 1
    },
    {
      label: "Choose which of your Creatures it attacks",
      pool: (s, db, pid) => creaturesControlledBy(s, db, pid),
      min: 1,
      max: 1
    }
  ],
  resolvePower: (ctx) => {
    if (ctx.powerName !== "Skulk") return;
    const slots = ctx.chosenSlotIds;
    if (!slots || slots.length !== 2) return;
    const forcedAttackerId = slots[0]?.[0];
    if (!forcedAttackerId) return;
    const forcedAttacker = findCreatureOrMagiById(ctx.state, forcedAttackerId);
    if (!forcedAttacker || !isValidTargetGivenFlexibility(ctx.state, ctx.cardDb, ctx.controllingPlayer.playerId, forcedAttacker, "Creature")) return;
    if (forcedAttacker.controllerId === ctx.controllingPlayer.playerId) return;
    if (!effectiveRegions(ctx.state, ctx.cardDb, forcedAttacker).includes(regionForTargetFilter(ctx.state, "Weave"))) return;
    discardEnergy(ctx.state, ctx.cardDb, forcedAttacker, 1, void 0, void 0, ctx.rng);
    checkForDefeats(ctx.state, ctx.cardDb);
    if (!findInPlayById(ctx.state, forcedAttackerId)) return;
    const defenderId = slots[1]?.[0];
    if (!defenderId) return;
    const defender = findInPlayById(ctx.state, defenderId);
    if (!defender || defender.controllerId !== ctx.controllingPlayer.playerId) return;
    const declaration = { attackerInstanceId: forcedAttackerId, defenderInstanceId: defenderId };
    if (!isLegalAttack(ctx.state, ctx.cardDb, forcedAttacker.controllerId, declaration, FORCED_ATTACK_OPTIONS).legal) return;
    declareAttack(
      ctx.state,
      ctx.cardDb,
      forcedAttacker.controllerId,
      declaration,
      {},
      ctx.rng,
      FORCED_ATTACK_OPTIONS
    );
  },
  // Region-swap sweep (Spell-pass audit follow-up, 2026-07-23) -- see targeting.ts's
  // regionForTargetFilter doc comment.
  specifiedTargetRegions: () => ["Weave"]
});

